            Q('i3', L('Per i compiti più difficili quale famiglia scegli?', 'Which family do you pick for the hardest tasks?'), ['Opus', 'Haiku', L('Nessuna', 'None'), L('Sempre la più piccola', 'Always the smallest')], 0, L('Il più capace della linea principale.', 'The most capable of the main line.')),
        ], task('text', L('Abbina un modello a ogni compito, uno per riga come `compito: famiglia`. Compiti: `classificare 100.000 email`, `progettare l’architettura di un’app complessa`. Famiglie: Haiku, Opus.', 'Match a model to each task, one per line as `task: family`. Tasks: `classify 100,000 emails`, `design a complex app’s architecture`. Families: Haiku, Opus.'), '', [re('(email)[^:\n]*:\s*Haiku', L('Volume alto: Haiku', 'High volume: Haiku')), re('(architettura|architecture)[^:\n]*:\s*Opus', L('Compito difficile: Opus', 'Hard task: Opus'))], '', "classificare 100.000 email: Haiku\nprogettare l’architettura di un’app complessa: Opus"), [
            dMatch(pMatch(), [['Anthropic', L('L’azienda', 'The company')], ['Haiku', L('Veloce ed economico', 'Fast and inexpensive')], ['Sonnet', L('Equilibrio, ottimo per il codice', 'Balanced, great for code')], ['Opus', L('Il più capace della linea principale', 'Most capable of the main line')]], L('Le famiglie di Claude.', 'Claude’s families.')),
            dFlash(pFlash(), [[L('Claude si può usare via API', 'Claude can be used via API'), true], [L('Anthropic è una divisione di Google', 'Anthropic is a division of Google'), false], [L('Haiku è pensato per velocità e costi bassi', 'Haiku is designed for speed and low cost'), true], [L('Le versioni dei modelli non cambiano mai', 'Model versions never change'), false]], L('Conoscere la famiglia.', 'Knowing the family.')),
        ]),
        lesson('features', L('Progetti, artefatti e connettori', 'Projects, artifacts and connectors'), [
            P('I **progetti** raccolgono chat, documenti di riferimento e istruzioni per uno stesso lavoro: Claude li tiene presenti in ogni conversazione del progetto. Gli **artefatti** sono contenuti a parte (documenti, codice, pagine web interattive, grafici) che Claude crea e aggiorna accanto alla chat.', '**Projects** collect chats, reference documents and instructions for the same piece of work: Claude keeps them in mind in every conversation in the project. **Artifacts** are standalone pieces of content (documents, code, interactive web pages, charts) that Claude creates and updates next to the chat.'),
            P('Claude analizza **file e immagini** caricati, può **cercare sul web** e, con i **connettori**, accedere a strumenti come calendario, email o documenti aziendali. Molti connettori usano il **Model Context Protocol** (MCP), lo standard aperto creato da Anthropic per collegare l’AI a strumenti e dati.', 'Claude analyses uploaded **files and images**, can **search the web** and, through **connectors**, access tools such as calendar, email or company documents. Many connectors use the **Model Context Protocol** (MCP), the open standard Anthropic created to connect AI to tools and data.'),
        ], [
