            Q('c3', L('Dove scegli se le chat aiutano a migliorare i modelli?', 'Where do you choose whether chats help improve models?'), [L('Nelle impostazioni dell’account', 'In the account settings'), L('Nel codice', 'In the code'), L('Non si può', 'You cannot'), L('Al telefono', 'By phone')], 0, L('Negli account personali.', 'In personal accounts.')),
        ], task('text', L('Scrivi un breve `CLAUDE.md` con tre regole per un progetto PHP, una per riga che inizia con `-`, tra cui come si **lanciano i test**.', 'Write a short `CLAUDE.md` with three rules for a PHP project, one per line starting with `-`, including how to **run the tests**.'), "# Regole del progetto\n- \n- \n- ", [re('^-\s*\S.*\n-\s*\S.*\n-\s*\S', L('Tre regole', 'Three rules')), re('test', L('Come lanciare i test', 'How to run tests')), re('PHP|php', L('Parla del progetto PHP', 'It is about the PHP project'))], '', "# Regole del progetto\n- PHP 8.3, codice con declare(strict_types=1)\n- lancia i test con: php vendor/bin/phpunit\n- non modificare i file in vendor/"), [
            dOrder(pSort(), ['cd mio-progetto', 'claude', L('> descrivi la modifica da fare', '> describe the change to make'), L('Approva i comandi proposti', 'Approve the proposed commands'), L('Controlla il diff prima del commit', 'Review the diff before committing')], L('Una sessione con Claude Code.', 'A Claude Code session.')),
            dFlash(pFlash(), [[L('Claude Code chiede i permessi prima di agire', 'Claude Code asks permission before acting'), true], [L('Conviene fare commit senza guardare le modifiche', 'Committing without looking at changes is wise'), false], [L('Le chat in incognito non restano in cronologia', 'Incognito chats do not stay in history'), true], [L('Claude Code funziona solo su telefono', 'Claude Code only works on phones'), false]], L('Agente sì, ma sotto controllo.', 'An agent, but under control.')),
        ]),
        lesson('api', L('L’API di Claude', 'The Claude API'), [
            P('Dalla **Claude Console** crei una chiave API e la metti in una variabile d’ambiente. L’API si paga a token, separatamente dagli abbonamenti a claude.ai. Gli SDK ufficiali esistono per Python, TypeScript, Java, Go, Ruby, C# e PHP.', 'From the **Claude Console** you create an API key and put it in an environment variable. The API is paid per token, separately from claude.ai subscriptions. Official SDKs exist for Python, TypeScript, Java, Go, Ruby, C# and PHP.'),
            C('import anthropic

