            Q('a2', L('Com’è fatta la risposta dell’API?', 'What does the API response look like?'), [L('Un elenco di blocchi di contenuto', 'A list of content blocks'), L('Una sola stringa', 'A single string'), L('Un’immagine', 'An image'), L('Un file ZIP', 'A ZIP file')], 0, L('Si controlla il tipo di ogni blocco.', 'You check each block’s type.')),
            Q('a3', L('Quale parametro è obbligatorio oltre a model e messages?', 'Which parameter is required besides model and messages?'), ['max_tokens', 'temperature', 'top_k', 'seed'], 0, L('Il tetto della risposta.', 'The answer cap.')),
        ], task('python', L('Completa la chiamata con `model="claude-opus-5-5"`, `max_tokens=800` e un messaggio `user` che chiede `"Spiegami le closure in JavaScript"`; poi stampa il testo dei blocchi di tipo `text`.', 'Complete the call with `model="claude-opus-5-5"`, `max_tokens=800` and a `user` message asking `"Spiegami le closure in JavaScript"`; then print the text of `text` blocks.'), "import anthropic\nclient = anthropic.Anthropic()\n", [re('client\.messages\.create\s*\(', L('La chiamata', 'The call')), re('model\s*=\s*["\']claude-opus-5-5["\']', L('Il modello', 'The model')), re('max_tokens\s*=\s*800', L('Il tetto', 'The cap')), re('["\']content["\']\s*:\s*["\']Spiegami le closure in JavaScript["\']', L('La domanda', 'The question')), re('if\s+\w+\.type\s*==\s*["\']text["\']\s*:\s*\n\s+print\s*\(\s*\w+\.text\s*\)', L('Stampi i blocchi di testo', 'You print the text blocks'))], '', "msg = client.messages.create(\n    model=\"claude-opus-5-5\",\n    max_tokens=800,\n    messages=[{\"role\": \"user\", \"content\": \"Spiegami le closure in JavaScript\"}],\n)\nfor b in msg.content:\n    if b.type == \"text\":\n        print(b.text)"), [
            dBlanks(pFill(), "msg = client.messages.___(\n    model=\"claude-opus-5-5\",\n    ___=1024,\n    messages=[{\"role\": \"___\", \"content\": \"Ciao\"}],\n)", ['create', 'max_tokens', 'user'], ['send', 'tokens', 'assistant'], L('La chiamata minima.', 'The minimal call.')),
            dBug(pBug(), ['msg = client.messages.create(model="claude-opus-5-5", max_tokens=1024, messages=m)', 'print(msg.text)'], 1, 'print("".join(b.text for b in msg.content if b.type == "text"))', L('Il testo sta nei blocchi di `msg.content`.', 'The text lives in the blocks of `msg.content`.')),
